List<PathSegmentImpl> function ( URI u , boolean decode ) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if ( u == null ) {
        return pathSegments;
    }
    try {
        String path = u.getPath();
        if ( path == null || path.isEmpty() ) {
            return pathSegments;
        }
        // If the path is absolute, remove the leading '/'
        if ( path.startsWith("/") ) {
            path = path.substring(1);
        }
        String[] segments = path.split("/");
        for ( String segment : segments ) {
            String decodedSegment = decode ? URLDecoder.decode(segment, "UTF-8") : segment;
            pathSegments.add(new PathSegmentImpl(decodedSegment));
        }
    } catch ( UnsupportedEncodingException e ) {
        throw new RuntimeException(e);
    }
    return pathSegments;
}

