public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Invalid escape character at end of string");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    int value = 0;
                    for (int j = 1; j <= 4; j++) {
                        char digit = str.charAt(i + j);
                        if (digit >= '0' && digit <= '9') {
                            value = (value << 4) + digit - '0';
                        } else if (digit >= 'a' && digit <= 'f') {
                            value = (value << 4) + digit - 'a' + 10;
                        } else if (digit >= 'A' && digit <= 'F') {
                            value = (value << 4) + digit - 'A' + 10;
                        } else {
                            throw new Exception("Invalid Unicode escape sequence");
                        }
                    }
                    sb.append((char) value);
                    i += 4; // Move past the Unicode sequence
                    break;
                default:
                    throw new Exception("Invalid escape character");
            }
            i++; // Move past the escaped character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

