public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the paths by trimming and ensuring they start with a slash
    path = path.trim();
    relativePath = relativePath.trim();

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a list to build the final path
    List<String> resultPath = new ArrayList<>(Arrays.asList(pathComponents));

    // Process each component of the relative path
    for (String component : relativePathComponents) {
        if ("..".equals(component)) {
            // Go up one directory if possible
            if (resultPath.size() > 1) {
                resultPath.remove(resultPath.size() - 1);
            }
        } else if (".".equals(component) || component.isEmpty()) {
            // Ignore current directory and empty components
            continue;
        } else {
            // Add the component to the path
            resultPath.add(component);
        }
    }

    // Join the components back into a single string
    return String.join("/", resultPath);
}

