static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Calculate the first day of the current month
        int firstDayOfMonth = 1;

        // Calculate the offset for the day step
        int dayOffset = (day - firstDayOfMonth) / dayStep * dayStep;

        // Calculate the new day
        int newDay = firstDayOfMonth + dayOffset;

        // Return the new time bucket
        return year * 10000 + month * 100 + newDay;
    } catch (Exception e) {
        // Handle unexpected issues gracefully
        return timeBucket;
    }
}

