public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("CharSequence must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be non-negative and index + length must be less than or equal to the length of the CharSequence");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4; // surrogate pair
            i++; // skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

